/**
 * Recording into an arrangement: what a take keeps of what came in, and the
 * clip it becomes. Pure: the frames come from an input recorder, the notes
 * from a MIDI input, the clip goes to the arrangement as one command, so one
 * undo takes the whole take away (REC-007, REC-009, REC-010).
 */
import type { Note } from "@audio-ui/core/piano-roll";
import {
  type Arranged,
  withEdgeFades,
} from "@/lib/arrangement";

/** What came in from an input, block by block: each block's first frame on the audio clock, and its channels. */
export interface RecordedBlock {
  channels: readonly Float32Array[];
  frame: number;
}

/**
 * Where on the audio clock a take's sound was played: `from` and `to` on the
 * arrangement, in seconds, while playback ran from `playFrom` at clock frame
 * `playAt`. What came in at a clock frame was played `latency` seconds
 * earlier (the input's and the output's, REC-008), so the frames are that
 * much later.
 */
export function takeFrames({
  from,
  latency,
  playAt,
  playFrom,
  sampleRate,
  to,
}: {
  from: number;
  latency: number;
  playAt: number;
  playFrom: number;
  sampleRate: number;
  to: number;
}): readonly [number, number] {
  const frameOf = (time: number) =>
    playAt + Math.round((time - playFrom + latency) * sampleRate);
  return [frameOf(from), frameOf(Math.max(from, to))];
}

/** The frames `[from, to)` of the clock out of `blocks`, as one channel array each: silence where no block came in. */
export function sliceBlocks(
  blocks: readonly RecordedBlock[],
  [from, to]: readonly [number, number],
  channelCount: number
): Float32Array[] {
  const length = Math.max(0, to - from);
  const channels = Array.from(
    { length: channelCount },
    () => new Float32Array(length)
  );
  for (const block of blocks) {
    const blockLength = block.channels[0]?.length ?? 0;
    const start = Math.max(from, block.frame);
    const end = Math.min(to, block.frame + blockLength);
    if (start >= end) {
      continue;
    }
    for (const [index, channel] of channels.entries()) {
      const source = block.channels[index] ?? block.channels[0];
      if (source) {
        channel.set(
          source.subarray(start - block.frame, end - block.frame),
          start - from
        );
      }
    }
  }
  return channels;
}

/** The loudest sample of a block, over its channels: what a take drawn live shows of it. */
export function blockPeak(block: RecordedBlock): number {
  let peak = 0;
  for (const channel of block.channels) {
    for (const sample of channel) {
      peak = Math.max(peak, Math.abs(sample));
    }
  }
  return peak;
}

/** The clip an audio take becomes: from where it started, as long as it lasted, over what lies under it. */
export function audioTakeClip({
  id,
  length,
  name,
  recording,
  start,
  track,
}: {
  id: string;
  length: number;
  name: string;
  recording: string;
  start: number;
  track: string;
}): Arranged {
  return {
    id,
    name,
    recording,
    sourceLength: length,
    track,
    value: withEdgeFades({ length, offset: 0, start }),
  };
}

/** A note played while recording, on the arrangement: where it started and ended, in seconds. A note still held has no end. */
export interface PlayedNote {
  end?: number;
  pitch: number;
  start: number;
  /** 0…1. */
  velocity: number;
}

/** The record quantizations: none, or a note value as a share of a whole note. */
export const RECORD_QUANTIZE = [0, 1 / 4, 1 / 8, 1 / 16, 1 / 32] as const;

/**
 * The notes of a MIDI take between `from` and `to`, in seconds from `origin`:
 * each as long as it was held (to `to` when it is still held), its start moved
 * to the nearest `quantize` seconds from `origin` when it is not 0 (REC-009).
 */
export function takeNotes(
  played: readonly PlayedNote[],
  {
    from,
    idPrefix,
    origin,
    quantize = 0,
    to,
  }: {
    from: number;
    idPrefix: string;
    origin: number;
    quantize?: number;
    to: number;
  }
): Note[] {
  const notes: Note[] = [];
  for (const [index, note] of played.entries()) {
    const end = Math.min(note.end ?? to, to);
    if (note.start >= to || end <= from) {
      continue;
    }
    const begin = Math.max(note.start, from);
    const placed =
      quantize > 0
        ? origin + Math.round((begin - origin) / quantize) * quantize
        : begin;
    notes.push({
      id: `${idPrefix}-${index + 1}`,
      length: Math.max(1e-3, end - begin),
      pitch: note.pitch,
      start: placed - origin,
      velocity: note.velocity,
    });
  }
  return notes;
}

/** The MIDI clip a take becomes, from `from` to `to` on the arrangement, over what lies under it. */
export function midiTakeClip({
  from,
  id,
  name,
  played,
  quantize,
  to,
  track,
}: {
  from: number;
  id: string;
  name: string;
  played: readonly PlayedNote[];
  quantize?: number;
  to: number;
  track: string;
}): Arranged {
  const length = Math.max(0, to - from);
  return {
    id,
    name,
    notes: takeNotes(played, {
      from,
      idPrefix: id,
      origin: from,
      quantize,
      to,
    }),
    sourceLength: length,
    track,
    value: { fadeIn: 0, fadeOut: 0, length, offset: 0, start: from },
  };
}

/**
 * A MIDI clip with a take's notes added to its own (Overdub on, REC-009):
 * placed in its source's time, so they sound where they were played.
 */
export function overdubbed(
  clip: Arranged,
  played: readonly PlayedNote[],
  {
    from,
    quantize,
    to,
  }: {
    from: number;
    quantize?: number;
    to: number;
  }
): Arranged {
  const origin = clip.value.start - clip.value.offset;
  const taken = Math.max(clip.value.start, from);
  const added = takeNotes(played, {
    from: taken,
    idPrefix: `${clip.id}-take-${(clip.notes ?? []).length}`,
    origin,
    quantize,
    to: Math.min(to, clip.value.start + clip.value.length),
  });
  return { ...clip, notes: [...(clip.notes ?? []), ...added] };
}

import { loadWorklet } from "@audio-ui/engine/worklet";
import type { RecordedBlock } from "@/lib/recording";

const PROCESSOR = "audioui-input-recorder";

/**
 * The recorder's processor: while it records, it copies each block of its
 * input with the block's first frame on the audio clock and posts it out. It
 * has no output, so what it records is never heard through it.
 */
const WORKLET = `class InputRecorder extends AudioWorkletProcessor {
  constructor() {
    super();
    this.recording = false;
    this.port.onmessage = (event) => {
      this.recording = event.data === "start";
      if (event.data === "stop") {
        this.port.postMessage({ stopped: true });
      }
    };
  }
  process(inputs) {
    const input = inputs[0];
    if (this.recording && input && input.length > 0) {
      const channels = input.map((channel) => channel.slice());
      this.port.postMessage(
        { channels, frame: currentFrame },
        channels.map((channel) => channel.buffer)
      );
    }
    return true;
  }
}
registerProcessor("${PROCESSOR}", InputRecorder);`;

/** An input recorder on a context, as `createInputRecorder` makes it. */
export interface InputRecorder {
  dispose: () => void;
  /** Connect what to record here, in stereo: a mono input is in both channels. It is only listened to, never heard. */
  readonly input: AudioNode;
  /** Keeps what comes in from the next block on. */
  start: () => void;
  /** Stops keeping, and gives every block kept since `start`, the last one in. */
  stop: () => Promise<RecordedBlock[]>;
}

/**
 * Records what is connected to it, block by block, each with its frame on the
 * audio clock: what `takeFrames` and `sliceBlocks` cut a take from (REC-007,
 * REC-008). `onBlock` hears each block as it comes, to draw the take live.
 * `null` when the context cannot run worklets.
 */
export async function createInputRecorder(
  ctx: BaseAudioContext,
  onBlock?: (block: RecordedBlock) => void
): Promise<InputRecorder | null> {
  if (!(await loadWorklet(ctx, WORKLET))) {
    return null;
  }
  const node = new AudioWorkletNode(ctx, PROCESSOR, {
    channelCount: 2,
    channelCountMode: "explicit",
    numberOfInputs: 1,
    numberOfOutputs: 0,
  });
  let blocks: RecordedBlock[] = [];
  // While it stops: the one answer every `stop` gets, and what gives it.
  let stopping: Promise<RecordedBlock[]> | null = null;
  let settle: (() => void) | null = null;
  node.port.onmessage = (
    event: MessageEvent<RecordedBlock | { stopped: true }>
  ) => {
    if ("stopped" in event.data) {
      settle?.();
      return;
    }
    blocks.push(event.data);
    onBlock?.(event.data);
  };
  return {
    dispose: () => {
      settle?.();
      node.port.close();
      node.disconnect();
    },
    input: node,
    start: () => {
      blocks = [];
      stopping = null;
      node.port.postMessage("start");
    },
    stop: () => {
      stopping ??= new Promise((resolve) => {
        settle = () => {
          settle = null;
          resolve(blocks);
        };
        node.port.postMessage("stop");
      });
      return stopping;
    },
  };
}

/** How long a count-in click rings, in seconds. */
const CLICK_SECONDS = 0.03;

/**
 * Clicks a count-in on `ctx` from `at` seconds of its clock: `beats` beats
 * `beatSeconds` apart, the first of every `beatsPerBar` higher, straight to
 * the output (REC-005). The take starts on the beat after the last.
 */
export function playCountIn(
  ctx: BaseAudioContext,
  {
    at,
    beatSeconds,
    beats,
    beatsPerBar,
  }: { at: number; beatSeconds: number; beats: number; beatsPerBar: number }
): void {
  for (let beat = 0; beat < beats; beat += 1) {
    const time = at + beat * beatSeconds;
    const tone = ctx.createOscillator();
    const level = ctx.createGain();
    tone.frequency.value = beat % beatsPerBar === 0 ? 1600 : 1000;
    level.gain.setValueAtTime(0.3, time);
    level.gain.exponentialRampToValueAtTime(0.001, time + CLICK_SECONDS);
    tone.connect(level).connect(ctx.destination);
    tone.start(time);
    tone.stop(time + CLICK_SECONDS);
  }
}
